import{_ as i,C as c,o as l,c as h,j as d,a as o,E as e,aj as r}from"./chunks/framework.DkvuVDKz.js";const q=JSON.parse('{"title":"LoadingBar 加载条","description":"","frontmatter":{},"headers":[],"relativePath":"components/loading-bar.md","filePath":"components/loading-bar.md","lastUpdated":1789294316000}'),s={name:"components/loading-bar.md"},b={id:"loadingbar-加载条",tabindex:"-1"};function u(g,t,p,m,f,x){const n=c("Badge"),a=c("XhDemo");return l(),h("div",null,[d("h1",b,[t[0]||(t[0]=o("LoadingBar 加载条 ",-1)),e(n,{type:"info",text:"alpha"}),t[1]||(t[1]=o()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#loadingbar-加载条","aria-label":'Permalink to "LoadingBar 加载条 <Badge type="info" text="alpha" />"'},"​",-1))]),t[3]||(t[3]=r('<p>页面顶部那条细进度线：表示&quot;正在去往别处&quot;或&quot;正在取数据&quot;。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/loading-bar" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/loading-bar.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/loading-bar" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/loading-bar" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/loading-bar.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>条子贴在视口顶边（往页面最上方看）；不给 value 就是不确定进度，宽度自行往前爬，loading 翻 false 才冲到头并淡出</p>',4)),e(a,{src:"loading-bar/01-basic"}),t[4]||(t[4]=r('<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to &quot;组件结构&quot;">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;loading-bar&quot;</code>：<strong><code>root</code></strong> · <code>track</code> · <strong><code>range</code></strong> · <code>peg</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="确定进度" tabindex="-1">确定进度 <a class="header-anchor" href="#确定进度" aria-label="Permalink to &quot;确定进度&quot;">​</a></h3><p>传了 value 就由宿主说了算，宽度照它显示，内部爬升不再插手；loading 仍然负责露面与收起</p>',6)),e(a,{src:"loading-bar/02-determinate"}),t[5]||(t[5]=d("h3",{id:"厚度与颜色",tabindex:"-1"},[o("厚度与颜色 "),d("a",{class:"header-anchor",href:"#厚度与颜色","aria-label":'Permalink to "厚度与颜色"'},"​")],-1)),t[6]||(t[6]=d("p",null,"height 数字按像素、字符串按任意 CSS 长度；color 只改进度段的底色",-1)),e(a,{src:"loading-bar/03-appearance"}),t[7]||(t[7]=d("h3",{id:"关掉爬升",tabindex:"-1"},[o("关掉爬升 "),d("a",{class:"header-anchor",href:"#关掉爬升","aria-label":'Permalink to "关掉爬升"'},"​")],-1)),t[8]||(t[8]=d("p",null,"trickle 为 false 时条子停在起步值 minimum 不动，往前走全靠宿主收尾",-1)),e(a,{src:"loading-bar/04-trickle"}),t[9]||(t[9]=d("h3",{id:"颜色",tabindex:"-1"},[o("颜色 "),d("a",{class:"header-anchor",href:"#颜色","aria-label":'Permalink to "颜色"'},"​")],-1)),t[10]||(t[10]=d("p",null,"tone 只换进度段的底色（取柔和档）；条子本身是 fixed，这里给它写死 absolute 并配一个相对定位的框子，六条才留在示例里而不是叠到页面顶边",-1)),e(a,{src:"loading-bar/05-tone"}),t[11]||(t[11]=d("h3",{id:"挂在局部",tabindex:"-1"},[o("挂在局部 "),d("a",{class:"header-anchor",href:"#挂在局部","aria-label":'Permalink to "挂在局部"'},"​")],-1)),t[12]||(t[12]=d("p",null,"条子默认贴视口顶边，改写成 absolute 再套一个相对定位的框子，它就只贴这块卡片的上沿",-1)),e(a,{src:"loading-bar/06-container"}),t[13]||(t[13]=r('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>路由切换、整页数据刷新这类用户无需等待具体百分比的过程。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>进度是确定的且用户关心具体数值：用<a href="./progress">进度条</a>。</li><li>局部区域在加载：用<a href="./skeleton">骨架屏</a>或<a href="./spinner">加载指示器</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>不给确定进度时自动爬升（<code>trickle</code>）：先快后慢，永远不到 100%，收到完成信号才补满。</li><li><code>minimum</code> 是起跳位置，让用户立刻看到反应。</li><li>可以挂在局部容器上而不只是页面顶部。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h3><ul><li>与路由守卫配合：进入时启动，完成或失败时收掉。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h3><ul><li>失败也要收掉：留在页面上的半截进度条比什么都没有更糟。</li><li>极快的请求可以延迟一点再显示，否则只会闪一下。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h3><ul><li>爬升到 100% 却还没加载完：用户以为卡死了。</li><li>同时挂好几条。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to &quot;API 参考&quot;">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-loading-bar&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhLoadingBarPeg</code> <code>XhLoadingBarRange</code> <code>XhLoadingBarRoot</code> <code>XhLoadingBarTrack</code></td></tr><tr><td>组合式函数</td><td><code>useLoadingBar</code></td></tr><tr><td>状态机</td><td><code>loadingBarMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/loading-bar.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>number</code></td><td></td><td>受控进度值（0-100）。给了它就是确定进度：宽度照它显示，内部爬升停止。</td></tr><tr><td><code>defaultValue</code></td><td><code>number</code></td><td></td><td>非受控初值，缺省 0。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>加载开关：true 开始，false 结束（冲到 100 再淡出归零）。只由宿主写入，无配套回调。</td></tr><tr><td><code>height</code></td><td><code>string | number</code></td><td></td><td>条子厚度：数字按像素，字符串按任意 CSS 长度。缺省 2px。</td></tr><tr><td><code>color</code></td><td><code>string</code></td><td></td><td>进度段颜色（任意 CSS 颜色）。不给就用皮肤的品牌色。</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定进度段用哪族颜色。给了 color 就以 color 为准。</td></tr><tr><td><code>trickle</code></td><td><code>boolean</code></td><td></td><td>不确定进度时自行往前爬，默认开。关掉即停在起步值等宿主收尾。</td></tr><tr><td><code>trickleSpeed</code></td><td><code>number</code></td><td></td><td>爬升节拍毫秒，默认 200；&lt;=0 或非有限数等同于关掉爬升。</td></tr><tr><td><code>minimum</code></td><td><code>number</code></td><td></td><td>起步值，默认 8：开始加载时先跳到这里。</td></tr><tr><td><code>fadeDuration</code></td><td><code>number</code></td><td></td><td>冲到 100 之后留给淡出的窗口毫秒，默认 200。窗口走完才归零并收起。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;LoadingBarTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>onValueChange</code></td><td><code>(details: LoadingBarValueChangeDetails) =&gt; void</code></td><td></td><td>进度值变化。不确定进度下每爬一步、冲到 100、归零各通知一次。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>LoadingBarValueChangeDetails</code></td><td>进度值变化；detail 为 <code>{ value: number }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhLoadingBarRoot</code></td><td><code>default</code></td><td><code>LoadingBarRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>track</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>range</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>peg</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr></tbody></table><p>以下名称仅用于内部状态机。</p><p><strong>状态</strong>：<code>idle</code> · <code>loading</code> · <code>finishing</code></p><p><strong>事件</strong>：<code>LOADING.START</code> · <code>LOADING.END</code> · <code>TRICKLE.SYNC</code> · <code>after.trickleSpeed</code> · <code>after.fadeDuration</code></p><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>LoadingBarPhase</code></td><td></td></tr><tr><td><code>value</code></td><td><code>number</code></td><td>当前显示的进度值（0-100，已夹取），也是 range 的宽度百分比。</td></tr><tr><td><code>visible</code></td><td><code>boolean</code></td><td>条子是否露面：idle 之外都露面。</td></tr><tr><td><code>indeterminate</code></td><td><code>boolean</code></td><td>不确定进度：没给 value，宽度自行爬升，不输出 aria-valuenow。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTrackProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getRangeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPegProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>进度段末端那道亮边。纯装饰，作者不渲染它时条子照旧成立。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h3><p>规格出处：<a href="https://www.w3.org/TR/wai-aria-1.2/#progressbar" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to &quot;ARIA&quot;">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations.root</td></tr><tr><td><code>root</code></td><td><code>aria-valuemax</code></td><td>String(LOADING_BAR_MAX)</td></tr><tr><td><code>root</code></td><td><code>aria-valuemin</code></td><td>&#39;0&#39;</td></tr><tr><td><code>root</code></td><td><code>aria-valuenow</code></td><td>String(value) | undefined</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;progressbar&#39;</td></tr><tr><td><code>peg</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to &quot;样式参考&quot;">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to &quot;皮肤&quot;">​</a></h3><p><code>@xihan-ui/styles/loading-bar.css</code> 使用 <code>[data-scope=&quot;loading-bar&quot;][data-part=&quot;root&quot;]</code> 部件选择器，位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-indeterminate</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>track</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>range</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr><tr><td><code>peg</code></td><td><code>data-state</code></td><td>&#39;idle&#39; | &#39;loading&#39; | &#39;finishing&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-loading-bar-fade</code></td><td><code>root</code></td><td><code>transition</code></td><td><code>default</code></td><td><code>--xh-motion-duration-exit</code></td><td>loading-bar 的 root 部件 transition 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-layer</code></td><td><code>root</code></td><td><code>z-index</code></td><td><code>default</code></td><td><code>--xh-layer-sticky</code></td><td>loading-bar 的 root 部件 z-index 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-peg-fg</code></td><td><code>peg</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-loading-bar-range</code></td><td>loading-bar 的 peg 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-peg-w</code></td><td><code>peg</code></td><td><code>inline-size</code></td><td><code>default</code></td><td><code>--xh-space-8</code></td><td>loading-bar 的 peg 部件 inline-size 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-range</code></td><td><code>peg</code><br><code>range</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-_tone-soft</code></td><td>loading-bar 的 peg、range 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-speed</code></td><td><code>range</code></td><td><code>transition</code></td><td><code>default</code></td><td><code>--xh-motion-duration-enter</code></td><td>loading-bar 的 range 部件 transition 覆盖槽。</td></tr><tr><td><code>--xh-loading-bar-track</code></td><td><code>track</code></td><td><code>background</code></td><td><code>default</code></td><td><code>transparent</code></td><td>loading-bar 的 track 部件 background 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h3><p><code>inline-size</code> · <code>opacity</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p><code>prefers-reduced-motion: reduce</code> 下本组件另有降级规则。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p>',54))])}const P=i(s,[["render",u]]);export{q as __pageData,P as default};
